<template>
  <main class="content-page document-page"><header class="tool-heading"><p class="section-kicker">SPACE / DOCUMENT STUDIO</p><h1>换个格式，<br><span>文件留在你手里。</span></h1><p>PDF 转 Word、Word 转 PDF。免费、本机处理，无需注册。</p></header>
    <div class="document-layout"><section class="conversion-workbench"><div class="document-drop" @dragover.prevent @drop.prevent="drop"><span class="document-icon" aria-hidden="true">↔</span><h2>{{file?file.name:'选择你的文档'}}</h2><p>{{file?`${kind.toUpperCase()} · ${(file.size/1024/1024).toFixed(2)} MB`:'拖放一个文件，或点击下方选择。支持 PDF / DOCX，单文件最多 10 MB。'}}</p><input ref="picker" class="file-picker" type="file" accept=".pdf,.docx" aria-label="选择 PDF 或 Word 文档" @change="choose($event.target.files)" /><button type="button" class="button button-primary" @click="picker.click()">{{file?'重新选择文件':'选择文件'}}</button></div>
      <div class="convert-settings"><label v-if="kind==='pdf'">PDF → Word 模式<select v-model="mode" :disabled="busy"><option value="editable">提取可编辑文字（重新排版）</option><option value="appearance">保留外观（每页嵌入图片，不可编辑文字）</option></select></label><p v-if="kind==='docx'">DOCX → PDF：保留常见标题、列表、表格和图片，按本页预览重新排版；导出为图像型 PDF，文字不可搜索。</p><div class="convert-buttons"><button type="button" class="button button-primary" :disabled="!file||busy" @click="prepare">{{busy?'正在本机处理…':'生成预览'}}</button><button v-if="busy" type="button" class="button button-secondary" @click="cancel">取消处理</button><button type="button" class="text-button" @click="clear">清除文件与结果</button></div><p v-if="busy" role="status">{{status}}<progress :value="progress" max="100" aria-label="本机转换进度" /></p><p v-if="error" class="convert-error" role="alert">{{error}}</p></div>
      <section v-if="preview" class="document-result"><div class="preview-heading"><h2>{{kind==='pdf'?'Word 输出预览':'PDF 重排预览'}}</h2><span>{{kind==='pdf'?preview.pages.length+' 个源页面':'导出时自动分页'}}</span></div><ul v-if="warnings.length" class="convert-warnings"><li v-for="warning in warnings" :key="warning">{{warning}}</li></ul><p v-if="kind==='pdf' && mode==='editable'">下方文字可编辑后导出。每个源页面单独生成一个 Word 节；复杂版式会重排，可能增加 Word 页数。</p>
        <div v-if="kind==='pdf'" class="pdf-pages"><article v-for="(page,i) in preview.pages" :key="i"><h3>源页面 {{i+1}}</h3><img v-if="mode==='appearance'" :src="page.image" :alt="`源 PDF 第 ${i+1} 页`" /><textarea v-else v-model="page.text" :aria-label="`编辑第 ${i+1} 页文字`" maxlength="60000" :placeholder="'此页没有可提取文字。扫描件可改选保留外观；首版未提供 OCR。'" /></article></div>
        <div v-else ref="wordPreview" class="word-preview" v-html="preview.html" />
        <div class="convert-buttons"><button type="button" class="button button-primary" :disabled="busy" @click="exportFile">{{busy?'正在生成文件…':`生成 ${kind==='pdf'?'Word':'PDF'} 下载文件`}}</button><a v-if="downloadUrl" class="button button-secondary download-file" :href="downloadUrl" :download="filename">下载 {{kind==='pdf'?'DOCX':'PDF'}}</a></div><p v-if="downloadUrl" class="download-note">结果已生成；点击下载后请打开核对。修改预览文字会清除旧下载，需重新生成。</p>
      </section><div v-else class="document-empty"><span>01 选择文件 → 02 核对预览 → 03 本地导出</span><p>不会偷偷上传文档，也不会在服务器保留转换历史。</p></div>
    </section><aside class="conversion-guide"><p class="section-kicker">KNOW THE LIMITS</p><h2>选对转换方式。</h2><h3>PDF → 可编辑 Word</h3><p>提取已有文字，不做 OCR，不恢复图片、表格结构或多栏排版。适合简单文字 PDF；需要准确版式时改选保留外观。</p><h3>PDF → 保留外观 Word</h3><p>每页渲染为图片嵌入 DOCX，适合扫描件及版式留存，但图片中的字不能直接编辑。外观不会变成可编辑表格。</p><h3>DOCX → PDF</h3><p>根据文档结构重排，而非调用微软 Word 引擎。原字体、页码、页眉页脚、批注、公式和复杂布局可能不保留。导出为图像型 PDF，适合一般阅读，不是可搜索或无障碍 PDF。</p><h3>隐私与限制</h3><p>文档在浏览器内处理，解析器资源来自本站。最多 12 页 PDF 或 12 页重排结果；仅支持未加密的 PDF / DOCX。不支持旧 DOC、宏文档和电子签名的保留。</p><p>DOCX 在独立 Worker 内解析，有超时和压缩尺寸检查；预览删除脚本、链接与外部图片。不下载文档引用的远程文件。</p><p>正式合同、论文及需要原版式的文档，请使用本机 Word / LibreOffice 的原生导出并人工核对。</p></aside></div>
  </main>
</template>
<script setup>
import { computed,onUnmounted,ref,watch } from 'vue'
import { outputName,validateFile } from '../features/documents/guards'
import { openDocx,openPdf,pagesToWord,previewToPdf } from '../features/documents/converter'
const picker=ref(null),wordPreview=ref(null),file=ref(null),kind=ref(''),mode=ref('editable'),preview=ref(null),warnings=ref([]),busy=ref(false),error=ref(''),status=ref(''),progress=ref(0),downloadUrl=ref('');let controller,generation=0
const filename=computed(()=>outputName(file.value?.name||'document',kind.value==='pdf'?'docx':'pdf'))
function revoke(){if(downloadUrl.value)URL.revokeObjectURL(downloadUrl.value);downloadUrl.value=''}
function cancel(){generation++;controller?.abort();controller=null;busy.value=false;status.value='已取消，本机文件未上传。'}
function clear(){cancel();revoke();file.value=null;kind.value='';preview.value=null;warnings.value=[];error.value='';progress.value=0;if(picker.value)picker.value.value=''}
function choose(files){const selection=Array.from(files||[]);clear();if(selection.length!==1){error.value='请每次选择一个文档。';return}try{kind.value=validateFile(selection[0]);file.value=selection[0]}catch(ex){error.value=ex.message}}
function drop(event){choose(event.dataTransfer.files)}
watch(mode,()=>{cancel();revoke();preview.value=null;warnings.value=[];error.value=''})
watch(preview,revoke,{deep:true})
function update(current,total){progress.value=Math.round(current/total*100);status.value=`处理页面 ${current} / ${total}`}
async function prepare(){cancel();revoke();preview.value=null;warnings.value=[];error.value='';busy.value=true;progress.value=0;status.value='正在本机解析…';controller=new AbortController();const job=generation,signal=controller.signal
  try{const buffer=await file.value.arrayBuffer();if(signal.aborted)return;const result=kind.value==='pdf'?await openPdf(buffer,mode.value,signal,update):await openDocx(buffer,signal);if(job!==generation)return
    if(kind.value==='pdf'){if(mode.value==='editable'&&result.emptyPages===result.pages.length)throw Error('未检测到可提取文字：可能是扫描件。请改选“保留外观”，本页未进行 OCR。');preview.value={pages:result.pages.map(page=>({...page,text:page.lines.join('\n')}))};if(result.emptyPages)warnings.value.push(`${result.emptyPages} 页未检测到可提取文字。`)}else{preview.value={html:result.html};warnings.value=result.warnings.length?['解析器提示部分原始结构不支持；请核对预览。']:[]}
    progress.value=100;status.value='预览已生成。'
  }catch(ex){if(job===generation&&ex.name!=='AbortError')error.value=ex.message||'无法转换此文件。'}finally{if(job===generation)busy.value=false}
}
async function exportFile(){cancel();revoke();error.value='';busy.value=true;progress.value=0;status.value='正在生成本地文件…';controller=new AbortController();const job=generation,signal=controller.signal
  try{const blob=kind.value==='pdf'?await pagesToWord(preview.value.pages.map(page=>({...page,lines:page.text.split('\n')})),mode.value,signal):await previewToPdf(wordPreview.value,signal,update);if(job!==generation)return;downloadUrl.value=URL.createObjectURL(blob);status.value='可点击下载。';progress.value=100}catch(ex){if(job===generation&&ex.name!=='AbortError')error.value=ex.message||'生成文件失败。'}finally{if(job===generation)busy.value=false}
}
onUnmounted(()=>{cancel();revoke()})
</script>
<style scoped>
.tool-heading{padding:42px 0 30px}.tool-heading h1{font-size:clamp(38px,5vw,64px);line-height:1.15}.tool-heading h1 span{color:#0071e3}.tool-heading>p:last-child{font-size:18px;line-height:1.8;margin-top:22px}.document-layout{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(0,1fr);gap:24px}.conversion-workbench,.conversion-guide{min-width:0}.document-drop{padding:36px 24px;border:2px dashed #bfcee1;background:#fff;border-radius:24px;text-align:center}.document-icon{display:grid;place-items:center;width:64px;height:64px;border-radius:18px;margin:0 auto 20px;background:#edf5ff;color:#0071e3;font-size:32px}.document-drop h2{font-size:24px;overflow-wrap:anywhere}.document-drop p{font-size:16px;line-height:1.8;color:#60738a;margin:16px 0 24px}.file-picker{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}.convert-settings{padding:24px 4px}.convert-settings label{display:grid;gap:12px;font-size:16px;color:#465b74}.convert-settings select{width:100%;border:1px solid #cdd7e4;border-radius:12px;padding:12px;background:#fff;color:#30445b;font-size:16px}.convert-settings p{font-size:16px;color:#526980;line-height:1.9}.convert-buttons{display:flex;flex-wrap:wrap;gap:10px;margin-top:22px;align-items:center}.convert-error{color:#a62439!important}.convert-settings progress{display:block;width:100%;height:8px;margin-top:12px;accent-color:#0071e3}.conversion-guide,.document-result{padding:28px;border:1px solid #dfe4eb;background:#fff;border-radius:24px}.conversion-guide h3{font-size:18px;margin-top:26px}.conversion-guide p{font-size:16px;color:#586b81;line-height:1.9;margin:12px 0}.document-empty{padding:26px;border-radius:20px;background:#ebeff5;color:#546982;font-size:14px;line-height:1.9}.document-empty p{margin-top:12px}.preview-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.preview-heading h2{font-size:24px}.preview-heading span{font-size:14px;color:#75869a}.document-result>p,.download-note{font-size:14px;line-height:1.9;color:#64778e}.convert-warnings{padding:16px 16px 16px 32px;background:#fff8e6;border-radius:12px;font-size:14px;line-height:1.8;margin:18px 0;color:#735e2f}.pdf-pages{display:grid;gap:24px;margin:24px 0}.pdf-pages h3{font-size:16px;color:#5e748d;margin-bottom:12px}.pdf-pages textarea{width:100%;min-height:220px;resize:vertical;border:1px solid #d6deea;border-radius:12px;padding:18px;font-size:16px;line-height:1.8;color:#25384e;background:#fafbfd}.pdf-pages img{width:100%;height:auto;border:1px solid #e0e5ec}.word-preview{border:1px solid #dfe4eb;padding:22px;margin:22px 0;max-height:720px;overflow:auto;background:#fff;color:#172638;line-height:1.85;overflow-wrap:anywhere;font-size:16px}.word-preview :deep(img){max-width:100%;height:auto}.word-preview :deep(table){width:100%;border-collapse:collapse}.word-preview :deep(td),.word-preview :deep(th){border:1px solid #d9dfe7;padding:8px}.word-preview :deep(p){margin:12px 0}.word-preview :deep(h1){font-size:28px}.word-preview :deep(h2){font-size:24px}.word-preview :deep(h3){font-size:20px}button:disabled{opacity:.45;cursor:not-allowed}@media(max-width:850px){.document-layout{grid-template-columns:1fr}}@media(max-width:480px){.tool-heading{padding-top:24px}.conversion-guide,.document-result{padding:18px}.word-preview{padding:14px}}
</style>
